import{_ as e,o as a,c as i,ae as l}from"./chunks/framework.BuGep-IT.js";const y=JSON.parse('{"title":"Benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/benchmarks.md","filePath":"en/guide/benchmarks.md"}'),s={name:"en/guide/benchmarks.md"};function r(d,t,n,o,h,c){return a(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#benchmarks" aria-label="Permalink to &quot;Benchmarks {#benchmarks}&quot;">​</a></h1><p>This page presents the performance characteristics of <code>asyncmux</code>, measured with <code>benchmarks/asyncmux.bench.ts</code>. The numbers below are reference values from a specific environment and will vary across environments.</p><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology {#methodology}&quot;">​</a></h2><p>Measurements use the Vitest benchmarking feature. Each case runs repeatedly for about 0.5 seconds, and <code>ops/sec</code> is the number of executions per second.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./.config/vitest.bench.ts</span></span></code></pre></div><p>The measurement environment was as follows:</p><ul><li>CPU: 12th Gen Intel Core i9-12900K</li><li>Memory: 32 GiB</li><li>Node.js: v24.15.0</li><li>Date: 2026-09-08</li></ul><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results {#results}&quot;">​</a></h2><h3 id="uncontended" tabindex="-1">A. Uncontended lock acquisition <a class="header-anchor" href="#uncontended" aria-label="Permalink to &quot;A. Uncontended lock acquisition {#uncontended}&quot;">​</a></h3><p>Speed of <code>lock</code> / <code>rLock</code> acquisition and release with an empty queue.</p><table tabindex="0"><thead><tr><th>Case</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">Mean</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td><code>lock</code> / <code>release</code> (no key)</td><td style="text-align:right;">1,196,752</td><td style="text-align:right;">0.0008 ms</td><td style="text-align:right;">0.0012 ms</td></tr><tr><td><code>lock</code> / <code>release</code> (key)</td><td style="text-align:right;">972,952</td><td style="text-align:right;">0.0010 ms</td><td style="text-align:right;">0.0020 ms</td></tr><tr><td><code>rLock</code> / <code>release</code> (no key)</td><td style="text-align:right;">1,181,629</td><td style="text-align:right;">0.0008 ms</td><td style="text-align:right;">0.0011 ms</td></tr><tr><td><code>rLock</code> / <code>release</code> (key)</td><td style="text-align:right;">834,585</td><td style="text-align:right;">0.0012 ms</td><td style="text-align:right;">0.0015 ms</td></tr></tbody></table><h3 id="low-contention" tabindex="-1">B. Low contention <a class="header-anchor" href="#low-contention" aria-label="Permalink to &quot;B. Low contention {#low-contention}&quot;">​</a></h3><p>Two workers repeatedly acquiring and releasing a lock on the same key.</p><table tabindex="0"><thead><tr><th>Case</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">Mean</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>2 workers x 4 ops (same key)</td><td style="text-align:right;">77,059</td><td style="text-align:right;">0.0130 ms</td><td style="text-align:right;">0.0144 ms</td></tr><tr><td>2 workers x 16 ops (same key)</td><td style="text-align:right;">24,165</td><td style="text-align:right;">0.0414 ms</td><td style="text-align:right;">0.0397 ms</td></tr></tbody></table><h3 id="high-contention" tabindex="-1">C. High contention <a class="header-anchor" href="#high-contention" aria-label="Permalink to &quot;C. High contention {#high-contention}&quot;">​</a></h3><p>Many requests hitting the same lock at once.</p><table tabindex="0"><thead><tr><th>Case</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">Mean</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>32 concurrent requests (no key)</td><td style="text-align:right;">22,103</td><td style="text-align:right;">0.0452 ms</td><td style="text-align:right;">0.0425 ms</td></tr><tr><td>128 concurrent requests (same key)</td><td style="text-align:right;">2,011</td><td style="text-align:right;">0.4972 ms</td><td style="text-align:right;">0.5530 ms</td></tr></tbody></table><h3 id="repeated-lock-unlock" tabindex="-1">D. Repeated lock/unlock <a class="header-anchor" href="#repeated-lock-unlock" aria-label="Permalink to &quot;D. Repeated lock/unlock {#repeated-lock-unlock}&quot;">​</a></h3><p>A single worker acquiring and releasing a lock in a tight loop.</p><table tabindex="0"><thead><tr><th>Case</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">Mean</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>Sequential x 16</td><td style="text-align:right;">59,214</td><td style="text-align:right;">0.0169 ms</td><td style="text-align:right;">0.0172 ms</td></tr><tr><td>Sequential x 64</td><td style="text-align:right;">16,500</td><td style="text-align:right;">0.0606 ms</td><td style="text-align:right;">0.0582 ms</td></tr></tbody></table><h3 id="queued-operations" tabindex="-1">E. Queued operations <a class="header-anchor" href="#queued-operations" aria-label="Permalink to &quot;E. Queued operations {#queued-operations}&quot;">​</a></h3><p>Releasing a held lock to drain a queue of accumulated read/write requests at once.</p><table tabindex="0"><thead><tr><th>Case</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">Mean</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>Drain 50 queued R/W requests</td><td style="text-align:right;">13,877</td><td style="text-align:right;">0.0721 ms</td><td style="text-align:right;">0.0648 ms</td></tr><tr><td>Drain 200 queued R/W requests</td><td style="text-align:right;">3,044</td><td style="text-align:right;">0.3285 ms</td><td style="text-align:right;">7.4403 ms</td></tr></tbody></table><h3 id="error-path" tabindex="-1">F. Error path <a class="header-anchor" href="#error-path" aria-label="Permalink to &quot;F. Error path {#error-path}&quot;">​</a></h3><p>Exceptional paths such as double release or acquisition with an already-aborted signal.</p><table tabindex="0"><thead><tr><th>Case</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">Mean</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>Double release (throws <code>LockReleasedError</code>)</td><td style="text-align:right;">222,488</td><td style="text-align:right;">0.0045 ms</td><td style="text-align:right;">0.0065 ms</td></tr><tr><td>Immediately aborted signal (rejects)</td><td style="text-align:right;">159,919</td><td style="text-align:right;">0.0063 ms</td><td style="text-align:right;">0.0068 ms</td></tr></tbody></table><h3 id="cancellation" tabindex="-1">G. Cancellation <a class="header-anchor" href="#cancellation" aria-label="Permalink to &quot;G. Cancellation {#cancellation}&quot;">​</a></h3><p>Cancelling a queued acquisition via <code>AbortSignal</code>.</p><table tabindex="0"><thead><tr><th>Case</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">Mean</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>Abort while waiting in queue</td><td style="text-align:right;">106,592</td><td style="text-align:right;">0.0094 ms</td><td style="text-align:right;">0.0087 ms</td></tr></tbody></table><h3 id="realistic-workload" tabindex="-1">H. Realistic workload <a class="header-anchor" href="#realistic-workload" aria-label="Permalink to &quot;H. Realistic workload {#realistic-workload}&quot;">​</a></h3><p>Cache-like load mixing 12 reads, 3 writes, and 1 global write.</p><table tabindex="0"><thead><tr><th>Case</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">Mean</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>Mixed R/W access (12R + 3W + global W)</td><td style="text-align:right;">43,378</td><td style="text-align:right;">0.0231 ms</td><td style="text-align:right;">0.0230 ms</td></tr></tbody></table><h2 id="how-to-read" tabindex="-1">How to read the results <a class="header-anchor" href="#how-to-read" aria-label="Permalink to &quot;How to read the results {#how-to-read}&quot;">​</a></h2><p>Uncontended lock acquisition exceeds 1 million ops/sec, so the overhead of exclusive control attached to ordinary asynchronous work is negligible. There is no large speed gap between read and write locks, and specifying a key makes little difference. Even under high contention with 128 simultaneous requests, each request completes in about 0.5 ms, and a realistic mixed read/write load exceeds 40,000 ops/sec.</p>',34)])])}const u=e(s,[["render",r]]);export{y as __pageData,u as default};
